{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Didanosine showed absolute oral bioavailability of 40–50% in HIV-infected men after a 200 mg oral dose, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C03"],
      "claim": "Saquinavir showed absolute oral bioavailability of 4% (range 1–9%) in humans, supporting F < 20%."
    },
    {
      "card_ids": ["C13"],
      "claim": "R1479 showed estimated absolute oral bioavailability of 6–18% in humans, supporting F < 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C03", "C13"],
  "decision_summary": "Nine of ten transferred evidence molecules support low oral bioavailability below 20%, including absolute human values of 4%, 7%, 10%, and 6–18%; only didanosine supports high bioavailability in adults. Low is therefore better supported.",
  "evidence_gaps": [
    "Several records are qualitative ('poor', 'low') or do not specify absolute bioavailability type.",
    "Didanosine bioavailability varies by population and dose, with some pediatric values below 20%."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C02"],
  "revision_action": "initial",
  "supportive_card_ids": ["C02"]
}

